BUTTON_ACK = "✅ I'm on it"
BUTTON_REACHED = "🏥 We reached hospital"


def render(template_id: str, language: str = "en", **values: object) -> str:
    """Render a fixed template. Uses the English master unless drafts are approved."""
    lang = language if TRANSLATIONS_APPROVED and (template_id, language) in TEMPLATES else "en"
    text = TEMPLATES[(template_id, lang)]
    for key, val in values.items():
        text = text.replace("{" + key + "}", str(val))
    return text


def alert_text(level: str, subjects: list[str], language: str, **values: object) -> str:
    if level == "red":
        tid = "ALERT_RED_FAMILY" if "mother" in subjects or not subjects else "ALERT_RED_FAMILY_BABY"
    else:
        tid = "ALERT_AMBER_FAMILY"
    return render(tid, language, **values)


def reminder_text(level: str, language: str, **values: object) -> str:
    instruction = render("REMINDER_RED" if level == "red" else "REMINDER_AMBER", language, **values)
    return render("ESCALATION_REMINDER", language, instruction=instruction, **values)


def ticket_buttons(ticket_id: str) -> list[list[tuple[str, str]]]:
    return [[(BUTTON_ACK, f"ack:{ticket_id}")], [(BUTTON_REACHED, f"reached:{ticket_id}")]]


def plain_reason(reason_text: str) -> str:
    """The danger sign in plain words; drops the internal '(level kept)' style notes."""
    parts = [p.strip() for p in reason_text.split(";") if p.strip() and "level kept" not in p]
    return "; ".join(dict.fromkeys(parts)) or "A danger sign was reported."
